@media screen and (min-width: 900px) {
  .rollover-grid {
    display: grid;
    grid-template-columns: 1fr 1fr 1fr;
    grid-template-rows: auto;
    grid-row-gap: 10px;
    grid-column-gap: 60px;
    margin-left: 20px;
    margin-right: 20px;
  }

  .rollover-container-l {
    display: grid;
    grid-row: 1/2;
    grid-column: 1/2;
    grid-template-columns: auto;
    grid-template-rows: auto auto auto;
  }

  .rollover-container-c {
    display: grid;
    grid-row: 1/2;
    grid-column: 2/3;
    grid-template-columns: auto;
    grid-template-rows: auto auto auto;
  }

  .rollover-container-r {
    display: grid;
    grid-row: 1/2;
    grid-column: 3/4;
    grid-template-columns: auto;
    grid-template-rows: auto auto auto;
  }

  .rollover-h3-container {
    grid-row: 1/2;
    grid-column: 1/2;
  }

  .rollover-container-img-left {
    grid-row: 2/3;
    grid-column: 1/2;
    background-image: url(https://sites.rmit.edu.au/rmitstudios/files/2018/08/Import-course-2-1cbpfrd.svg);
    background-size: cover;
    background-repeat: no-repeat;
    background-position: center;
    padding-top: 35%;
    padding-bottom: 35%;
    margin-top: 25px;
    margin-bottom: 25px;
  }

  .rollover-container-img-centre {
    grid-row: 2/3;
    grid-column: 1/2;
    background-image: url(https://sites.rmit.edu.au/rmitstudios/files/2018/08/New-course-3-1xz41b9.svg);
    background-size: cover;
    background-repeat: no-repeat;
    background-position: center;
    padding-top: 35%;
    padding-bottom: 35%;
    margin-top: 25px;
    margin-bottom: 25px;
  }

  .rollover-container-img-right {
    grid-row: 2/3;
    grid-column: 1/2;
    background-image: url(https://sites.rmit.edu.au/rmitstudios/files/2018/08/Get-help-2-2jt98yk.svg);
    background-size: cover;
    background-repeat: no-repeat;
    background-position: center;
    padding-top: 35%;
    padding-bottom: 35%;
    margin-top: 25px;
    margin-bottom: 25px;
  }

  .rollover-text-container {
    grid-row: 3/4;
    grid-column: 1/2;
  }

  .rollover-2col {
    display: grid;
    grid-template-columns: 50% 50%;
    grid-template-rows: auto;
  }

  .rollover-2col-left {
    grid-row: 1/2;
    grid-column: 1/2;
    border-right: 1px solid #0a8eaf;
    padding: 0px 40px 0px 20px;
    margin-top: 20px;
  }

  .rollover-2col-right {
    grid-row: 1/2;
    grid-column: 2/3;
    padding: 0px 20px 0px 40px;
    margin-top: 20px;
  }

  .rollover-wash {
    opacity: 0.3;
  }

  .rollover-mockup {
    background-image: url(https://sites.rmit.edu.au/rmitstudios/files/2018/08/Mockup-2-zy956q.svg);
    background-size: cover;
    background-repeat: no-repeat;
    background-position: center;
    padding-top: 35%;
    padding-bottom: 35%;
    margin-top: 25px;
    margin-bottom: 25px;
  }

  .rollover-button {
    border-radius: 50px;
    background-color: #a32b00;
    padding: 10px;
    text-align: center;
    margin-left: auto;
    margin-right: auto;
    margin-bottom: 25px;
  }

  .rollover-button:hover {
    background-color: #000054;
  }

  #content .user_content .rollover-button a {
    text-decoration: none;
    color: #FFFFFF;
    font-weight: bold;
    font-size: 18px;
  }
}
