/*
Common Customisations

Purpose/Description: 
AUDIO AND PODCAST BLOCK – AND IMAGE WITH CAPTION

Author(s):
Carly Milanovic

Contributor(s):
*/
.audio-container {
  display: inline-block;
  width: 100%;
  padding: 1rem;
  box-sizing: border-box;
}

.audio-container .audio-container-image {
  float: left;
  margin-right: 1rem;
  margin-bottom: 1rem;
  display: inline-flex;
}

.audio-container .audio-container-image.left img {
  left: 0;
}

.audio-container .audio-container-image.centered img {
  left: -50px;
}

.audio-container .audio-container-image.right img {
  right: 0;
}

.audio-container .audio-container-image .audio-container-image-wrapper {
  overflow: hidden !important;
  width: 150px;
  height: 150px;
  display: inline-block;
  position: relative;
}

.audio-container .audio-container-image .audio-container-image-wrapper img {
  max-width: 250px !important;
  position: absolute;
}

.audio-container .video-container {
  padding: 20px !important;
  margin: 0.5rem 0;
  width: auto;
  display: block;
  clear: both;
  box-sizing: border-box;
}

.audio-container .audio-text {
  display: inline-block;
  width: calc(100% - 170px);
}

.audio-container .audio-text p:not(.specialHeading) {
  font-size: 0.9rem !important;
}

.audio-container .audio-text .specialHeading {
  margin: 0 0 1rem 0;
  padding: 0.2rem 1rem !important;
}

.preview-container .audio-container-image {
  position: relative;
  margin: 0.5rem;
  padding: 1rem;
}

.preview-container .audio-container-image.left::before, .preview-container .audio-container-image.centered::before, .preview-container .audio-container-image.right::before {
  width: 200px;
  height: 100%;
  position: absolute;
  content: "";
  position: absolute;
  margin-top: -1rem;
}

.preview-container .audio-container-image.left:before {
  box-shadow: 106px 0px rgba(255, 255, 255, 0.85);
  border-right: 4px dashed #0072ff;
  left: 1rem;
}

.preview-container .audio-container-image.centered:before {
  border-left: 4px dashed #0072ff;
  border-right: 4px dashed #0072ff;
  box-shadow: 106px 0px rgba(255, 255, 255, 0.85), -106px 0px rgba(255, 255, 255, 0.85);
  margin: -1rem calc(50% - 120px);
}

.preview-container .audio-container-image.right:before {
  border-left: 4px dashed #0072ff;
  right: 1rem;
  box-shadow: -204px 0px rgba(255, 255, 255, 0.85);
}

.preview-container img {
  max-width: 300px;
}

