.icon-with-image {
  background-size: cover;
  background-position: center;
  display: inline-block;
  border: 3px solid;
  border-color: #000054;
  height: 50px;
  width: 50px;
  border-radius: 50%;
}

.icon-with-image i {
  border-radius: inherit;
  width: inherit;
  height: inherit;
  position: relative;
  z-index: -1;
  overflow: hidden;
}

.icon-with-image i::before {
  position: absolute;
  overflow: hidden;
  width: inherit;
  height: inherit;
}

.icon-with-image i img {
  display: none;
  width: inherit;
  height: inherit;
  border-radius: inherit;
  pointer-events: none;
}

.icon-with-image i.icon-none img {
  display: inherit;
  width: 100%;
}

.icon-with-image.small-icon {
  height: 50px;
  width: 50px;
}

.icon-with-image.small-icon i::before {
  top: 20%;
  left: 20%;
  font-size: 30px !important;
}

.icon-with-image.medium-icon {
  height: 100px;
  width: 100px;
}

.icon-with-image.medium-icon i::before {
  top: 30%;
  left: 30%;
  font-size: 42px !important;
}

.icon-with-image.large-icon {
  height: 200px;
  width: 200px;
}

.icon-with-image.large-icon i::before {
  top: 26%;
  left: 26%;
  font-size: 94px !important;
}

.icon-with-image.circle-icon {
  border-radius: 50%;
}

.icon-with-image.square-icon {
  border-radius: 10%;
}

.icon-with-image.square-icon i {
  border-radius: 8%;
}

.icon-with-image.solid-light {
  border: 3px solid;
  border-color: #fff;
}

.icon-with-image.solid-dark {
  border: 3px solid;
  border-color: #000054;
}

.icon-with-image.no-border {
  border: none;
}

.icon-with-image.colour-dark i::before {
  color: #000054;
}

.icon-with-image.colour-light i::before {
  color: white;
}

.icon-with-image.background-red i {
  background-color: #e60028;
}

.icon-with-image.background-blue i {
  background-color: #000054;
}

.icon-with-image.background-white i {
  background-color: white;
}

.iframe-container {
